// Auto-assign issues based on issue type
// Attach as a listener for ISSUE_CREATED events

var issueData = issueData || {};
var issueType = issueData.issueTypeName || '';

var assignMap = {
  'Bug': null,         // set to userId string
  'Story': null,
  'Task': null,
  'Epic': null
};

var targetUser = assignMap[issueType];
if (targetUser && issueId) {
  jdc.issue.setFieldValue('assigneeId', targetUser);
  jdc.log.info('Auto-assigned ' + issueType + ' to ' + targetUser);
}

true;

// Condition: Block transition if any subtask is unresolved

var subtasks = jdc.issue.getSubtasks();
var allResolved = true;

for (var i = 0; i < subtasks.length; i++) {
  var st = subtasks[i];
  var status = st.statusName || st.status || '';
  if (status !== 'Done' && status !== 'Closed' && status !== 'Resolved') {
    allResolved = false;
    break;
  }
}

allResolved;

// Validator: Require a comment on transition

var transitionComment = comment || '';
var screenComment = screenInput ? (screenInput.comment || '') : '';

if (!transitionComment && !screenComment) {
  'A comment is required for this transition';
} else {
  null; // pass validation
}

// Post-function: Cascade priority to subtasks

var parentPriority = jdc.issue.getFieldValue('priorityId');
var subtasks = jdc.issue.getSubtasks();

for (var i = 0; i < subtasks.length; i++) {
  var stId = subtasks[i].id;
  if (stId && parentPriority) {
    jdc.issue.setFieldValue.call({ context: { issueId: stId } }, 'priorityId', parentPriority);
    jdc.log.info('Updated subtask ' + stId + ' priority');
  }
}

true;

// Calculated field: Days since creation

var issueInfo = jdc.issue.getCurrentIssue();
var createdAt = issueInfo.createdAt || issueInfo.created;

if (createdAt) {
  var created = new Date(createdAt);
  var now = new Date();
  var diffMs = now.getTime() - created.getTime();
  var diffDays = Math.floor(diffMs / (1000 * 60 * 60 * 24));
  diffDays + ' days';
} else {
  'N/A';
}

// Post-function: Send email on transition

var toStatus = toStatusId;
var issueInfo = jdc.issue.getCurrentIssue();
var issueKey = issueInfo.issueKey || 'Unknown';
var summary = issueInfo.summary || 'No summary';

// Customize: target status and recipient
var targetStatus = 'DONE_STATUS_ID';  // replace with actual status ID
var recipientEmail = 'team@example.com';

if (toStatus === targetStatus) {
  var subject = issueKey + ' has been completed';
  var body = '<h3>' + issueKey + ': ' + summary + '</h3><p>This issue was moved to Done by ' + (userData.displayName || 'a user') + '.</p>';
  email.sendEmail(recipientEmail, subject, body);
  jdc.log.info('Completion email sent for ' + issueKey);
}

true;

// Scheduled: Bulk transition stale issues
// Run on a schedule (e.g., daily at 9am)

var staleJql = 'status = "Open" AND updated < -30d';
var transitionId = 'YOUR_TRANSITION_ID';  // replace with actual transition ID

var issues = jdc.search.jql(staleJql, 100);
jdc.log.info('Found ' + issues.length + ' stale issues');

var success = 0;
for (var i = 0; i < issues.length; i++) {
  var issue = issues[i];
  if (jdc.issue.transitionIssue(issue.id, transitionId)) {
    success++;
    jdc.issue.addComment.call({ context: { issueId: issue.id } }, 'Auto-closed: inactive for 30+ days');
  }
}

jdc.log.info('Transitioned ' + success + ' of ' + issues.length + ' stale issues');
success;

// Listener: Call external webhook on issue update
// Configure http-whitelist-domains in application.yml first

var webhookUrl = 'https://hooks.example.com/jdc';

var payload = {
  event: eventType,
  issueId: issueId,
  projectId: projectId,
  userId: userId,
  timestamp: new Date().toISOString()
};

var response = http.post(webhookUrl, payload, {
  'Content-Type': 'application/json',
  'X-JDC-Event': eventType
});

if (response && response.status === 200) {
  jdc.log.info('Webhook delivered for ' + eventType);
} else {
  jdc.log.warn('Webhook failed: ' + JSON.stringify(response));
}

true;

// Field behavior: Hide environment for Epics
// Returns an array of field directives

var issueType = issueData ? issueData.issueTypeName : '';
var directives = [];

if (issueType === 'Epic') {
  directives.push({
    fieldName: 'environment',
    visible: false
  });
  directives.push({
    fieldName: 'storyPoints',
    visible: false
  });
}

// Make priority required for Bugs
if (issueType === 'Bug') {
  directives.push({
    fieldName: 'priority',
    required: true,
    warning: 'Priority is required for bug reports'
  });
}

directives;

// Utility library — include in other scripts with: include('template-utils-library')

function formatDate(date) {
  if (!date) return 'N/A';
  var d = new Date(date);
  return d.getFullYear() + '-' +
    String(d.getMonth() + 1).padStart(2, '0') + '-' +
    String(d.getDate()).padStart(2, '0');
}

function daysBetween(date1, date2) {
  var d1 = new Date(date1);
  var d2 = new Date(date2);
  return Math.floor(Math.abs(d2 - d1) / (1000 * 60 * 60 * 24));
}

function isBusinessDay(date) {
  var d = new Date(date);
  var day = d.getDay();
  return day !== 0 && day !== 6;
}

function addBusinessDays(startDate, numDays) {
  var current = new Date(startDate);
  var added = 0;
  while (added < numDays) {
    current.setDate(current.getDate() + 1);
    if (isBusinessDay(current)) added++;
  }
  return current;
}

function truncate(str, maxLen) {
  if (!str) return '';
  return str.length > maxLen ? str.substring(0, maxLen) + '...' : str;
}
